input.command:
cat > Cargo.toml <<'EOF'
[package]
name = "wintool"
version = "0.1.0"
edition = "2024"
description = "Windows-only tool using raw Win32 API bindings"
publish = false

# Raw, zero-overhead FFI bindings to the Win32 API. Enable additional
# `Win32_*` features as you need more of the API surface; each feature
# corresponds to a module under `windows_sys::Win32`.
[target.'cfg(windows)'.dependencies]
windows-sys = { version = "0.61.2", features = [
    "Win32_Foundation",
    "Win32_System_Threading",
    "Win32_UI_WindowsAndMessaging",
] }

[profile.release]
lto = true
codegen-units = 1
strip = true
EOF
mkdir -p .cargo && cat > .cargo/config.toml <<'EOF'
# Default to the MSVC Windows target so `cargo build` / `cargo check`
# target Windows even when run from another host (e.g. CI or WSL).
# Override with `--target <triple>` if needed.
[build]
target = "x86_64-pc-windows-msvc"
EOF
cat > src/main.rs <<'EOF'
#[cfg(not(windows))]
compile_error!("wintool only supports Windows targets");

use windows_sys::Win32::System::Threading::GetCurrentProcessId;
use windows_sys::Win32::UI::WindowsAndMessaging::{MB_ICONINFORMATION, MB_OK, MessageBoxW};

/// Encodes a Rust string as a NUL-terminated UTF-16 buffer for `*W` Win32 APIs.
fn wide(s: &str) -> Vec<u16> {
    s.encode_utf16().chain(std::iter::once(0)).collect()
}

fn main() {
    // SAFETY: GetCurrentProcessId has no preconditions.
    let pid = unsafe { GetCurrentProcessId() };

    let text = wide(&format!("Hello from wintool (PID {pid})"));
    let caption = wide("wintool");

    // SAFETY: both pointers reference live, NUL-terminated UTF-16 buffers
    // that outlive the call; a null HWND means "no owner window".
    unsafe {
        MessageBoxW(
            std::ptr::null_mut(),
            text.as_ptr(),
            caption.as_ptr(),
            MB_OK | MB_ICONINFORMATION,
        );
    }
}
EOF
rustup target add x86_64-pc-windows-msvc 2>&1 | tail -1 && cargo check 2>&1 | tail -3 && cargo clippy 2>&1 | tail -3

